/* KiMapka BETA 0,3 — projects, named elements, arbitrary room boundaries and six-surface inventory. */
types.lan=['Gniazdo LAN','LAN'];types.rtv=['Gniazdo RTV','RTV'];types.sat=['Gniazdo SAT','SAT'];types.smart=['Gniazdo smart','Wi-Fi'];
types.wire=['Luźny przewód','⌁'];types.lamp=['Punkt świetlny','☼'];types.point=['Punkt pomiarowy','＋'];measureLabel.z='Wysokość / obniżenie';
const surfaceName=(i)=>i===-1?'Podłoga':i===-2?'Sufit':'Ściana '+String.fromCharCode(65+i);
const elName=e=>e.name?.trim()||types[e.type][0];
const copy=o=>JSON.parse(JSON.stringify(o));
function normalizeProject(raw){
 const d=raw?.format==='KiMapka'?raw.project:raw;
 if(!d||typeof d.name!=='string'||!Array.isArray(d.rooms)||!d.rooms.length||d.rooms.length>100)throw Error('Nieprawidłowy projekt KiMapka.');
 const idOK=s=>typeof s==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(s),num=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max,photo=s=>!s||(typeof s==='string'&&s.length<12000000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s));
 const p={id:idOK(d.id)?d.id:uid(),schema:2,name:d.name.slice(0,100),updatedAt:typeof d.updatedAt==='string'?d.updatedAt:new Date().toISOString(),rooms:[],links:[]};
 const ids=new Set();
 for(const old of d.rooms){
  if(!idOK(old.id)||ids.has(old.id)||typeof old.name!=='string'||!num(old.h,20,100000)||!num(old.x,-200000,200000)||!num(old.y,-200000,200000)||!Array.isArray(old.elements)||old.elements.length>1000)throw Error('Nieprawidłowe dane pomieszczenia.');ids.add(old.id);
  const points=old.points||Geom.rect(old.w,old.d);const error=Geom.polygonError(points);if(error)throw Error(error);
  const b=Geom.bounds(points),r={id:old.id,name:old.name.slice(0,60),h:old.h,w:b.w,d:b.d,x:old.x,y:old.y,points:points.map(q=>({x:q.x,y:q.y})),edges:[],elements:[],floorNote:String(old.floorNote||'').slice(0,500),ceilingNote:String(old.ceilingNote||'').slice(0,500),photo:photo(old.photo)?old.photo||'':''};
  r.edges=points.map((_,i)=>{const e=old.edges?.[i]||{kind:'wall'},L=Geom.edge(r,i).len;if(!['wall','open','partial'].includes(e.kind))throw Error('Nieprawidłowy rodzaj ściany.');if(e.kind==='partial'&&(!num(e.start,0,L)||!num(e.width,1,L)||e.start+e.width>L+.01))throw Error('Otwarcie wychodzi poza ścianę.');return {kind:e.kind,start:e.start||0,width:e.width||0}});
  const elementIds=new Set();for(const e of old.elements){if(!idOK(e.id)||elementIds.has(e.id)||!Object.hasOwn(types,e.type)||!Number.isInteger(e.wall)||e.wall< -2||e.wall>=points.length||!['x','y','w','h'].every(k=>num(e[k],k==='x'||k==='y'?-100000:0,100000))||!photo(e.photo)||e.z!==undefined&&!num(e.z,0,r.h))throw Error('Nieprawidłowy element lub zdjęcie.');elementIds.add(e.id);r.elements.push({id:e.id,type:e.type,name:String(e.name||types[e.type][0]).slice(0,80),wall:e.wall,x:e.x,y:e.y,w:e.w||80,h:e.h||80,z:e.z||0,note:String(e.note||'').slice(0,500),photo:e.photo||''})}
  p.rooms.push(r);
 }
 for(const l of d.links||[]){const a=p.rooms.find(r=>r.id===l.a),b=p.rooms.find(r=>r.id===l.b);if(a&&b&&idOK(l.id)&&Number.isInteger(l.wa)&&l.wa>=0&&l.wa<a.points.length&&Number.isInteger(l.wb)&&l.wb>=0&&l.wb<b.points.length&&num(l.t,0,2000)&&num(l.offset,-100000,100000))p.links.push({id:l.id,a:a.id,b:b.id,wa:l.wa,wb:l.wb,t:l.t,offset:l.offset})}return p;
}
let dirty=false,revision=0,saveTimer,writeChain=Promise.resolve(),projectReady=false;
function status(s){if($('#saveStatus'))$('#saveStatus').textContent=s}
save=function(){dirty=true;revision++;status('● Zmiany do zapisania…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>persistProject(),1500)};
async function persistProject(){clearTimeout(saveTimer);if(!projectReady)return false;if(!dirty)return true;const scope=ProjectStore.scope(),snap=copy(data),rev=revision;snap.updatedAt=new Date().toISOString();data.updatedAt=snap.updatedAt;let success=false;writeChain=writeChain.catch(()=>{}).then(async()=>{if(scope!==ProjectStore.scope()||!projectReady)return;try{await ProjectStore.put(snap);if(data.id===snap.id&&revision===rev){dirty=false;status('● Zapisano w chmurze')}success=true}catch(e){if(scope!==ProjectStore.scope())return;dirty=true;status('⚠ Niezapisane zmiany — eksportuj JSON');toast(e.message)}});await writeChain;return success}
function setProjectName(value){data.name=value.trim()||'Projekt';save();$('#projectName').textContent=data.name}
async function explicitSave(){const editing=$('#dialog').open&&$('#projectTitle');if(editing)setProjectName(editing.value);if(await persistProject()){toast('Zapisano projekt „'+data.name+'”.');if(editing)await projectDialog()}}
window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue=''}});
length=function(r,w){return w<0?r.w:Geom.edge(r,w).len};fits=function(r,e){return Geom.elementFits(r,e)&&e.z<=r.h};
selectRoom=function(id){roomId=id;wall=0;activeElement=null;activeField=null;shapeDraft=null;render()};
function chooseSurface(i){wall=i;activeElement=null;activeField=null;render()}
render=function(){if(!projectReady)return;const r=room();if(wall>=r.points.length)wall=0;$('#projectName').textContent=data.name;$('#heading').textContent=view==='plan'?'Plan całego lokalu':view==='shape'?'Obrys pomieszczenia':'Pomiar pomieszczenia';$('#rooms').innerHTML=data.rooms.map(a=>`<button class="room-item ${a.id===r.id?'active':''}" onclick="selectRoom('${a.id}')"><span>${esc(a.name)}</span><small>${(Geom.area(a.points)/1e6).toFixed(1)} m²</small></button>`).join('');$('#mobileRooms').innerHTML=data.rooms.map(a=>`<option value="${a.id}" ${a.id===r.id?'selected':''}>${esc(a.name)}</option>`).join('');$('#wallTab').classList.toggle('active',view!=='plan');$('#planTab').classList.toggle('active',view==='plan');if(view==='plan')renderPlan();else if(view==='shape')renderShape();else renderEditor()};
cell=function(r,e,key){const id=e?`cell-${e.id}-${key}`:`cell-room-${key}`,plane=e&&e.wall<0,label=plane?({x:'X rzutu',y:'Y rzutu',w:'Szerokość X',h:'Długość Y',z:'Wysokość / obniżenie'}[key]):measureLabel[key],v=e?e[key]:r[key];return `<div class="measurement-cell"><input id="${id}" aria-label="${esc(e?elName(e):r.name)}: ${label}" type="text" inputmode="text" data-dimension-math autocomplete="off" spellcheck="false" min="${plane&&['x','y'].includes(key)?-100000:['w','h','d'].includes(key)?1:0}" max="100000" value="${v}" onfocus="focusMeasure('${e?.id||''}','${key}')" oninput="editMeasure(this,'${e?.id||''}','${key}')" onblur="finishMeasure(this,'${e?.id||''}','${key}')" onkeydown="if(event.key==='Enter')this.blur()"><button aria-label="Zdjęcie: ${esc(e?elName(e):r.name)}, ${label}" onclick="openInlinePhoto('${id}','${e?.id||''}')">📷</button></div>`};
renderEditor=function(){const r=room(),plane=wall<0,els=r.elements.filter(e=>e.wall===wall);if(!els.some(e=>e.id===activeElement))activeElement=null;const edge=plane?null:r.edges[wall];$('#content').innerHTML=`<div class="editor-heading"><div><div class="eyebrow">BETA 0,3 · ${r.points.length} ODCINKÓW OBRYSU</div><input class="room-title" aria-label="Nazwa pokoju" value="${esc(r.name)}" maxlength="60" onchange="room().name=this.value.trim()||'Pokój';save();render()"></div><button onclick="view='shape';shapeDraft=null;render()">⌑ Edytuj obrys</button></div><div class="room-measures"><div><label>Rozpiętość obrysu X · mm</label>${cell(r,null,'w')}</div><div><label>Rozpiętość obrysu Y · mm</label>${cell(r,null,'d')}</div><div><label for="cell-room-h">Wysokość pomieszczenia · mm</label>${cell(r,null,'h')}</div></div><div class="surface-tabs">${r.points.map((_,i)=>`<button class="${wall===i?'active':''}" onclick="chooseSurface(${i})">${String.fromCharCode(65+i)}${r.edges[i].kind!=='wall'?' ◌':''}</button>`).join('')}<button class="${wall===-1?'active':''}" onclick="chooseSurface(-1)">▱ Podłoga</button><button class="${wall===-2?'active':''}" onclick="chooseSurface(-2)">▰ Sufit</button></div><div class="editor-stage"><div class="card wall-card"><div class="card-top"><h3>${surfaceName(wall)}</h3><span class="muted">${plane?'Widok z góry · Y w dół':edge.kind==='open'?'Otwarta granica':edge.kind==='partial'?'Ściana częściowo otwarta':'Widok od wnętrza'}</span></div><div class="drawing" id="wallCanvas">${wallSVG(r,wall)}</div><div class="drawing-bottom"><span>${plane?'X/Y od punktu (0,0) rzutu — sufit bez odbicia':'X od lewego końca · Y od podłogi'}</span><span id="dragReadout">Przeciągnij element</span></div></div><div class="card model-card"><div class="card-top"><h3>Podgląd 3D</h3><button class="tiny" onclick="open3D()">⤢ Powiększ</button></div><button class="model-mini" id="mini3D" onclick="open3D()" aria-label="Powiększ dynamiczny podgląd 3D"></button><div class="model-caption">Obrys, otwarcia i instalacje</div></div></div>${plane?`<div class="surface-note"><label for="surfaceNote">${wall===-1?'Podłoga — poziomy, materiał, uwagi':'Sufit — obniżenia, materiał, uwagi'}</label><input id="surfaceNote" value="${esc(wall===-1?r.floorNote:r.ceilingNote)}" maxlength="500" oninput="room()['${wall===-1?'floorNote':'ceilingNote'}']=this.value;save()" placeholder="np. nierówność przy oknie +12 mm, sufit podwieszany"></div>`:''}<div class="add-strip">${Object.entries(types).filter(([k])=>!plane||!['door','window','switch'].includes(k)).map(([k,t])=>`<button ${!plane&&edge.kind==='open'?'disabled':''} onclick="addInline('${k}')">${pictogram(k)} <span>${t[0]}</span></button>`).join('')}</div><div class="card table-card"><div class="card-top"><h3>${surfaceName(wall)} · edytuj komórki</h3><span class="muted">Własna nazwa, położenie i wymiary · mm</span></div><div class="measure-scroll"><table class="measure-table v2-table"><thead><tr><th>Nazwa elementu</th><th>X · ${plane?'rzut':'od lewej'}</th><th>Y · ${plane?'rzut':'od podłogi'}</th><th>Szer. X</th><th>${plane?'Długość Y':'Wysokość'}</th>${plane?'<th>Z · wys./obniż.</th>':''}<th>Opis</th><th></th></tr></thead><tbody>${els.map(e=>`<tr data-row="${e.id}" class="${activeElement===e.id?'selected':''}"><td><input class="element-name" aria-label="Nazwa elementu ${e.id}" value="${esc(elName(e))}" maxlength="80" oninput="renameElement('${e.id}',this.value)" onblur="if(!this.value.trim()){this.value=types['${e.type}'][0];renameElement('${e.id}',this.value)}"><small>${types[e.type][0]} · ${isOpening(e)?'krawędź':'środek / oś'}</small></td><td>${cell(r,e,'x')}</td><td>${cell(r,e,'y')}</td><td>${isOpening(e)?cell(r,e,'w'):'—'}</td><td>${isOpening(e)?cell(r,e,'h'):'—'}</td>${plane?`<td>${cell(r,e,'z')}</td>`:''}<td><input class="note-cell" aria-label="Opis ${esc(elName(e))}" value="${esc(e.note)}" maxlength="500" onchange="room().elements.find(e=>e.id==='${e.id}').note=this.value;save()"></td><td><button class="delete-inline" aria-label="Usuń ${esc(elName(e))}" onclick="deleteInline('${e.id}')">×</button></td></tr>`).join('')}</tbody></table>${els.length?'':'<div class="empty">Dodaj element. Nazwę wpiszesz bezpośrednio w pierwszej komórce.</div>'}</div></div><div id="editNotice" class="edit-notice" role="status">${plane?'Z: wysokość nad podłogą lub odległość w dół od sufitu. X/Y mają tę samą orientację na obu widokach.':'Nazwij przeszkodę np. „Grzejnik”, „Słup” albo „Belka”. Typ elementu pozostaje bez zmian.'}</div><section id="inlinePhoto" class="card" hidden><div class="card-top"><h3 id="photoHeading">Zdjęcie pomiaru</h3><button onclick="document.getElementById('inlinePhoto').hidden=true">Zwiń</button></div><div class="photo-body"><input id="photoInput" type="file" accept="image/*"><img id="photoPreview" class="photo-preview" hidden><div id="ocrPanel"></div><p class="muted">OCR eksperymentalny. Sprawdź wynik i jednostkę.</p></div></section>`;bindWallDrag();update3D();};
function renameElement(id,name){const e=room().elements.find(e=>e.id===id);if(!e)return;e.name=name;save();refreshWall();update3D()}
editMeasure=function(input,id,key){const r=room(),o=id?r.elements.find(e=>e.id===id):r,n=Number(input.value),min=id&&o.wall<0&&['x','y'].includes(key)?-100000:['w','h','d'].includes(key)?1:0;const next={...o,[key]:n};if(!id&&['w','d'].includes(key)&&Number.isFinite(n)&&n>0){const b=Geom.bounds(r.points),axis=key==='w'?'x':'y',base=axis==='x'?b.x:b.y,ratio=n/r[key];next.points=r.points.map(p=>({...p,[axis]:base+(p[axis]-base)*ratio}))}let error=input.value===''||!Number.isFinite(n)||n<min||n>100000;if(!error)error=id?!fits(r,next):!!Geom.polygonError(next.points)||next.edges.some((e,i)=>e.kind==='partial'&&e.start+e.width>Geom.edge(next,i).len)||r.elements.some(e=>!fits(next,e));if(error){input.classList.add('invalid');$('#editNotice').textContent='Nieprawidłowy wymiar: element musi mieścić się na powierzchni i poza otwartą częścią ściany.';return}input.classList.remove('invalid');o[key]=n;if(!id&&next.points!==r.points){r.points=next.points;data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id)}save();$('#editNotice').textContent='Zaktualizowano pomiar i model.';refreshGeometry()};
refreshGeometry=function(){refreshWall();update3D();if($('#roomArea'))$('#roomArea').textContent=(Geom.area(room().points)/1e6).toFixed(2)+' m²'};
addInline=function(type){const r=room(),L=wall>=0?length(r,wall):r.w;const e={id:uid(),wall,type,name:types[type][0],x:0,y:0,w:Math.min(type==='window'?1200:type==='door'?900:200,L),h:Math.min(type==='window'?1400:type==='door'?2100:200,wall<0?r.d:r.h),z:0,note:'',photo:''};let found=false;if(wall>=0){const g=Geom.gap(r,wall),starts=[500,0,g?.[1]||0];for(const x of starts){e.x=x;e.y=type==='door'?0:Math.min(300,r.h-(isOpening(e)?e.h:0));if(fits(r,e)){found=true;break}}}else{const b=Geom.bounds(r.points);for(let j=0;j<=20&&!found;j++)for(let i=0;i<=20;i++){e.x=Math.round(b.x+b.w*i/20);e.y=Math.round(b.y+b.d*j/20);if(fits(r,e)){found=true;break}}}if(!found){toast('Brak miejsca na domyślny element. Zmień obrys lub otwarcie ściany.');return}r.elements.push(e);activeElement=e.id;activeField={id:e.id,key:'x'};save();render();$(`#cell-${e.id}-x`)?.focus({preventScroll:true})};
const drawingInfo=(r,w)=>{const b=Geom.bounds(r.points),W=w<0?b.w:length(r,w),H=w<0?b.d:r.h,s=Math.min(580/W,250/H);return {s,ox:(720-W*s)/2,oy:60,bottom:60+H*s,W,H,b}};
wallSVG=function(r,w){const {s,ox,oy,bottom,W,H,b}=drawingInfo(r,w),plane=w<0;const p=q=>[ox+(q.x-b.x)*s,oy+(q.y-b.y)*s];let base=plane?`<polygon points="${r.points.map(q=>p(q).join(',')).join(' ')}" fill="#fff" stroke="none"/>${r.points.map((q,i)=>{const v=r.points[(i+1)%r.points.length],a=p(q),z=p(v),g=Geom.gap(r,i),L=Geom.edge(r,i).len;const part=(u,t,open)=>{const v1=[a[0]+(z[0]-a[0])*u/L,a[1]+(z[1]-a[1])*u/L],v2=[a[0]+(z[0]-a[0])*t/L,a[1]+(z[1]-a[1])*t/L];return `<path d="M${v1}L${v2}" stroke="${open?'#d39242':'#315674'}" stroke-width="${open?2:3}" ${open?'stroke-dasharray="6 5"':''}/>`};return `${g?part(0,g[0],false)+part(g[0],g[1],true)+part(g[1],L,false):part(0,L,false)}<text x="${(a[0]+z[0])/2+8}" y="${(a[1]+z[1])/2-8}" font-size="12" fill="#476b84">${String.fromCharCode(65+i)}</text>`}).join('')}`:`<rect x="${ox}" y="${oy}" width="${W*s}" height="${H*s}" fill="white" stroke="#315674" stroke-width="2"/>`;
if(!plane){const g=Geom.gap(r,w);if(g)base+=`<rect x="${ox+g[0]*s}" y="${oy}" width="${(g[1]-g[0])*s}" height="${H*s}" fill="#fcf2df" stroke="#ca8e3e" stroke-dasharray="7 6"/><text x="${ox+(g[0]+g[1])*s/2}" y="${oy+H*s/2}" text-anchor="middle" font-size="12" fill="#9f702f">OTWARTE</text>`}
const els=r.elements.filter(e=>e.wall===w).map(e=>{const x=ox+(e.x-(plane?b.x:0))*s,y=plane?oy+(e.y-b.y)*s:bottom-e.y*s,top=plane?y:y-e.h*s,on=e.id===activeElement,stroke=on?'#cb812c':'#4e7894';return `<g data-element="${e.id}" tabindex="0" role="button" aria-label="${esc(elName(e))}, X ${e.x}, Y ${e.y}" onkeydown="nudgeElement(event,'${e.id}')" style="cursor:grab;touch-action:none">${isOpening(e)?`<rect x="${x}" y="${top}" width="${e.w*s}" height="${e.h*s}" fill="${e.type==='window'?'#d3eaf0':'#e2eaf0'}" stroke="${stroke}" stroke-width="${on?3:2}"/><text x="${x+e.w*s/2}" y="${top+e.h*s/2}" text-anchor="middle" fill="#365873" font-size="11">${esc(elName(e))}</text>`:`<circle cx="${x}" cy="${y}" r="21" fill="transparent"/>${['water','socket','wire','lan','rtv','sat','smart'].includes(e.type)?`${on?`<rect x="${x-19}" y="${y-19}" width="38" height="38" rx="5" fill="none" stroke="${stroke}" stroke-width="2"/>`:''}${pictogram(e.type,`x="${x-16}" y="${y-16}" width="32" height="32"`)}`:`<circle cx="${x}" cy="${y}" r="11" fill="#e8eff5" stroke="${stroke}" stroke-width="${on?3:2}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="13">${types[e.type][1]}</text>`}`}<text x="${x}" y="${plane?top+e.h*s+15:Math.min(370,y+23)}" font-size="10" fill="#5b788b">${!isOpening(e)?esc(elName(e))+' · ':''}${e.x}/${e.y}</text></g>`}).join('');
return `<svg viewBox="0 0 720 390" aria-label="${surfaceName(w)} — pomiary" data-scale="${s}">${base}<text x="360" y="35" text-anchor="middle" fill="#365773" font-size="14">${Math.round(W)} mm</text><text x="${ox-18}" y="${oy+H*s/2}" text-anchor="middle" transform="rotate(-90 ${ox-18} ${oy+H*s/2})" fill="#365773" font-size="13">${Math.round(H)} mm</text>${els}<text x="${ox}" y="${bottom+43}" font-size="11" fill="#6d8799">${plane?`Punkt odniesienia: (0,0) rzutu · X →, Y ↓ · ${w===-2?'sufit bez odbicia':'podłoga'}`:'Poziom gotowej podłogi ±0 · X →, wysokość ↑'}</text></svg>`};
function moveElement(e,dx,dy){const trial={...e,x:Math.round(e.x+dx),y:Math.round(e.y+dy)};if(fits(room(),trial)){e.x=trial.x;e.y=trial.y;return true}return false}
bindWallDrag=function(){const svg=$('#wallCanvas svg');if(!svg)return;let drag;const point=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse());svg.onpointerdown=ev=>{const g=ev.target.closest('[data-element]');if(!g)return;ev.preventDefault();const e=room().elements.find(e=>e.id===g.dataset.element);activeElement=e.id;activeField={id:e.id,key:'x'};drag={e,g,p:point(ev),x:e.x,y:e.y};svg.setPointerCapture(ev.pointerId);document.querySelectorAll('[data-row]').forEach(r=>r.classList.toggle('selected',r.dataset.row===e.id))};svg.onpointermove=ev=>{if(!drag)return;const q=point(ev),s=+svg.dataset.scale,e=drag.e,trial={...e,x:Math.round(drag.x+(q.x-drag.p.x)/s),y:Math.round(drag.y+(q.y-drag.p.y)/s*(wall<0?1:-1))};if(fits(room(),trial)){e.x=trial.x;e.y=trial.y;drag.g.setAttribute('transform',`translate(${(e.x-drag.x)*s},${(e.y-drag.y)*s*(wall<0?1:-1)})`);for(const k of ['x','y'])$(`#cell-${e.id}-${k}`).value=e[k];$('#dragReadout').textContent=`X ${e.x} · Y ${e.y} mm`;update3D()}};const finish=ev=>{if(!drag)return;if(ev.type==='pointercancel'){drag.e.x=drag.x;drag.e.y=drag.y}drag=null;save();refreshGeometry();for(const k of ['x','y']){const e=room().elements.find(e=>e.id===activeElement);$(`#cell-${e.id}-${k}`).value=e[k]}};svg.onpointerup=finish;svg.onpointercancel=finish};
nudgeElement=function(ev,id){const step=ev.shiftKey?10:1,dirs={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,wall<0?-step:step],ArrowDown:[0,wall<0?step:-step]};if(!dirs[ev.key])return;ev.preventDefault();const e=room().elements.find(e=>e.id===id);moveElement(e,...dirs[ev.key]);activeElement=id;save();refreshGeometry();for(const k of ['x','y'])$(`#cell-${id}-${k}`).value=e[k];$(`[data-element="${id}"]`)?.focus({preventScroll:true})};
let shapeDraft=null;
function startDraft(){const r=room();shapeDraft={points:copy(r.points),edges:copy(r.edges),sources:r.points.map((_,i)=>i)}}
function draftChange(i,k,v){const n=Number(v);if(!Number.isFinite(n))return;shapeDraft.points[i][k]=n;refreshShape()}
function draftEdge(i,k,v){shapeDraft.edges[i][k]=k==='kind'?v:Number(v);if(k==='kind'&&v==='partial'&&!shapeDraft.edges[i].width){shapeDraft.edges[i].start=0;shapeDraft.edges[i].width=Math.min(900,Math.floor(Geom.edge({...room(),points:shapeDraft.points},i).len/2))}renderShape()}
function insertCorner(i){if(shapeDraft.points.length>=32){toast('Maksymalnie 32 narożniki.');return}const a=shapeDraft.points[i],b=shapeDraft.points[(i+1)%shapeDraft.points.length];shapeDraft.points.splice(i+1,0,{x:Math.round((a.x+b.x)/2),y:Math.round((a.y+b.y)/2)});shapeDraft.edges.splice(i+1,0,{kind:'wall',start:0,width:0});shapeDraft.sources.splice(i+1,0,null);renderShape()}
function removeCorner(i){if(shapeDraft.points.length<=3)return;shapeDraft.points.splice(i,1);shapeDraft.edges.splice(i,1);shapeDraft.sources.splice(i,1);renderShape()}
function presetDraft(kind){const r=room();if(r.elements.length&&!confirm('Zmiana wzoru może zmienić położenie ścian względem elementów. Przed zapisaniem obrys zostanie sprawdzony. Kontynuować?'))return;shapeDraft.points=Geom.template(kind,r.w,r.d);shapeDraft.edges=shapeDraft.points.map(()=>({kind:'wall',start:0,width:0}));shapeDraft.sources=shapeDraft.points.map((_,i)=>i<r.points.length?i:null);renderShape()}
function shapeSVG(){const p=shapeDraft.points,b=Geom.bounds(p),s=Math.min(580/Math.max(b.w,1),280/Math.max(b.d,1)),ox=(720-b.w*s)/2,oy=45;const pos=q=>[ox+(q.x-b.x)*s,oy+(q.y-b.y)*s];return `<svg id="shapeSvg" viewBox="0 0 720 390" data-scale="${s}" aria-label="Edytor obrysu"><polygon points="${p.map(q=>pos(q).join(',')).join(' ')}" fill="#e6f0f4" stroke="none"/>${p.map((q,i)=>{const a=pos(q),z=pos(p[(i+1)%p.length]),e=shapeDraft.edges[i],L=Math.hypot(z[0]-a[0],z[1]-a[1])/s;return `<path d="M${a}L${z}" stroke="${e.kind==='wall'?'#305a77':'#ce8e38'}" stroke-width="3" ${e.kind!=='wall'?'stroke-dasharray="7 5"':''}/><text x="${(a[0]+z[0])/2+10}" y="${(a[1]+z[1])/2-10}" font-size="12" fill="#496b81">${String.fromCharCode(65+i)} · ${Math.round(L)}</text><circle data-vertex="${i}" cx="${a[0]}" cy="${a[1]}" r="10" fill="#173d5c" stroke="white" stroke-width="2" style="cursor:grab"/><text x="${a[0]+12}" y="${a[1]+20}" font-size="11" fill="#173d5c">${i+1}</text>`}).join('')}</svg>`}
function refreshShape(){if($('#shapeDrawing')){$('#shapeDrawing').innerHTML=shapeSVG();bindShapeDrag()}if($('#shapeWarning'))$('#shapeWarning').textContent=Geom.polygonError(shapeDraft.points)||'Obrys poprawny. Zastosuj, aby zapisać i odświeżyć wszystkie widoki.'}
function renderShape(){if(!shapeDraft)startDraft();$('#content').innerHTML=`<div class="room-heading"><div><h2>Obrys · ${esc(room().name)}</h2><p class="muted">Narożniki kolejno dookoła pomieszczenia. X w prawo, Y w dół. Otwarta granica zachowuje powierzchnię podłogi.</p></div><button onclick="view='wall';shapeDraft=null;render()">Wróć</button></div><div class="shape-presets">${[['rect','Prostokąt'],['L','Kształt L'],['U','Kształt U'],['skos','Trapez / skosy']].map(([k,t])=>`<button onclick="presetDraft('${k}')">${t}</button>`).join('')}<button onclick="rotateDraft()">↻ Obróć 90°</button></div><div class="card"><div class="drawing" id="shapeDrawing">${shapeSVG()}</div></div><div id="shapeWarning" class="edit-notice" role="status"></div><div class="card measure-scroll"><table class="shape-table"><thead><tr><th>Narożnik</th><th>X · mm</th><th>Y · mm</th><th>Odcinek do następnego</th><th>Rodzaj</th><th>Otwarcie od · mm</th><th>Szer. otwarcia · mm</th><th></th></tr></thead><tbody>${shapeDraft.points.map((p,i)=>{const e=shapeDraft.edges[i];return `<tr><td>${i+1}</td><td><input aria-label="Narożnik ${i+1} X" type="number" step="1" value="${p.x}" onchange="draftChange(${i},'x',this.value)"></td><td><input aria-label="Narożnik ${i+1} Y" type="number" step="1" value="${p.y}" onchange="draftChange(${i},'y',this.value)"></td><td>${String.fromCharCode(65+i)} → ${i===shapeDraft.points.length-1?1:i+2}</td><td><select aria-label="Rodzaj ściany ${String.fromCharCode(65+i)}" onchange="draftEdge(${i},'kind',this.value)">${[['wall','Pełna ściana'],['open','Całkowicie otwarta'],['partial','Częściowo otwarta']].map(([k,t])=>`<option value="${k}" ${e.kind===k?'selected':''}>${t}</option>`).join('')}</select></td><td><input aria-label="Początek otwarcia ${i+1}" type="number" value="${e.start}" ${e.kind!=='partial'?'disabled':''} onchange="draftEdge(${i},'start',this.value)"></td><td><input aria-label="Szerokość otwarcia ${i+1}" type="number" value="${e.width}" ${e.kind!=='partial'?'disabled':''} onchange="draftEdge(${i},'width',this.value)"></td><td><button title="Dodaj narożnik na odcinku" onclick="insertCorner(${i})">＋</button><button title="Usuń narożnik" ${shapeDraft.points.length<=3?'disabled':''} onclick="removeCorner(${i})">×</button></td></tr>`}).join('')}</tbody></table></div><div class="shape-actions"><span class="muted">Zmiany obrysu są szkicem do chwili zastosowania.</span><button onclick="startDraft();renderShape()">Odrzuć szkic</button><button class="primary" onclick="applyShape()">Zastosuj obrys</button></div>`;refreshShape()}
function rotateDraft(){const b=Geom.bounds(shapeDraft.points);shapeDraft.points=shapeDraft.points.map(p=>({x:Math.round(b.x+b.d-(p.y-b.y)),y:Math.round(b.y+(p.x-b.x))}));renderShape()}
function bindShapeDrag(){const svg=$('#shapeSvg');let drag;const pt=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse());svg.onpointerdown=ev=>{const c=ev.target.closest('[data-vertex]');if(!c)return;ev.preventDefault();const i=+c.dataset.vertex;drag={i,p:pt(ev),original:{...shapeDraft.points[i]}};svg.setPointerCapture(ev.pointerId)};svg.onpointermove=ev=>{if(!drag)return;const p=pt(ev),s=+svg.dataset.scale;shapeDraft.points[drag.i]={x:Math.round(drag.original.x+(p.x-drag.p.x)/s),y:Math.round(drag.original.y+(p.y-drag.p.y)/s)};const c=svg.querySelector(`[data-vertex="${drag.i}"]`);c.setAttribute('transform',`translate(${p.x-drag.p.x},${p.y-drag.p.y})`);$('#shapeWarning').textContent='Przesuń narożnik i puść, aby sprawdzić obrys.'};svg.onpointerup=()=>{if(!drag)return;drag=null;renderShape()};svg.onpointercancel=()=>{if(drag)shapeDraft.points[drag.i]=drag.original;drag=null;renderShape()}}
function applyShape(){try{const error=Geom.polygonError(shapeDraft.points);if(error)throw Error(error);const r=room(),bounds=Geom.bounds(shapeDraft.points),next={...copy(r),points:copy(shapeDraft.points),edges:copy(shapeDraft.edges),w:bounds.w,d:bounds.d};for(let i=0;i<next.edges.length;i++){const e=next.edges[i],L=Geom.edge(next,i).len;if(e.kind==='partial'&&(!Number.isFinite(e.start)||!Number.isFinite(e.width)||e.start<0||e.width<=0||e.start+e.width>L))throw Error('Otwarcie na ścianie '+String.fromCharCode(65+i)+' wychodzi poza odcinek.')}next.elements=next.elements.map(e=>{if(e.wall>=0){const index=shapeDraft.sources.indexOf(e.wall);if(index<0)throw Error('Usuwany odcinek zawiera element „'+elName(e)+'”. Przenieś lub usuń go przed zmianą obrysu.');e.wall=index}if(!fits(next,e))throw Error('Nowy obrys koliduje z elementem „'+elName(e)+'”. Popraw jego położenie lub szkic.');return e});Object.assign(r,next);data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id);shapeDraft=null;wall=0;view='wall';save();render();toast('Zastosowano obrys. Połączenia tego pokoju ustaw ponownie.')}catch(e){$('#shapeWarning').textContent=e.message;toast(e.message)}}
roomDialog=function(){modal(`<h2>Nowe pomieszczenie</h2><form id="roomForm"><label>Nazwa</label><input name="name" value="Nowy pokój" maxlength="60" required><label>Kształt początkowy</label><select name="shape"><option value="rect">Prostokąt</option><option value="L">Kształt L</option><option value="U">Kształt U</option><option value="skos">Trapez / skosy</option></select><div class="fields">${[['w','Szerokość',4200],['d','Głębokość',3400],['h','Wysokość',2700]].map(([k,t,n])=>`<div><label>${t} · mm</label><input name="${k}" type="number" min="100" max="100000" value="${n}" required></div>`).join('')}</div><p class="muted">Narożniki i otwarcia można później zmieniać w „Edytuj obrys”.</p>${actions('Dodaj pokój')}</form>`);$('#roomForm').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),points=Geom.template(f.get('shape'),+f.get('w'),+f.get('d'));const r={id:uid(),name:f.get('name'),w:+f.get('w'),d:+f.get('d'),h:+f.get('h'),x:Math.max(...data.rooms.map(r=>r.x+Geom.bounds(r.points).x+r.w))+500,y:500,points,edges:points.map(()=>({kind:'wall',start:0,width:0})),elements:[],floorNote:'',ceilingNote:''};data.rooms.push(r);roomId=r.id;wall=0;view='wall';save();closeDialog();render()}};
projectDialog=async function(){let projects=[];try{projects=(await ProjectStore.list()).map(normalizeProject)}catch{toast('Lista projektów niedostępna. Możesz eksportować bieżący projekt.')}projects.sort((a,b)=>String(b.updatedAt).localeCompare(a.updatedAt));modal(`<h2>Moje projekty</h2><p class="muted">Prywatne projekty w chmurze. Limit beta: 5 MB na projekt, 20 MB / 100 projektów na konto. Eksport JSON to Twoja kopia zapasowa.</p><label>Nazwa bieżącego projektu</label><input id="projectTitle" value="${esc(data.name)}" maxlength="100" oninput="setProjectName(this.value)"><div class="project-actions"><button class="primary" onclick="explicitSave()">Zapisz projekt</button><button onclick="duplicateProject()">Zapisz jako kopię</button><button onclick="newProject()">＋ Nowy projekt</button><button onclick="backup()">↓ Eksport JSON</button><button onclick="document.getElementById('import').click()">↑ Import JSON</button></div><div class="project-list">${projects.length?projects.map(p=>`<div class="project-item"><div><b>${esc(p.name)}</b><small>${p.rooms.length} pomieszczeń · ${esc(new Date(p.updatedAt).toLocaleString('pl-PL'))}${p.id===data.id?' · bieżący':''}</small></div><button ${p.id===data.id?'disabled':''} onclick="openProject('${p.id}')">Otwórz</button></div>`).join(''):'<p>Jeszcze brak zapisanych projektów.</p>'}</div><div class="dialog-actions"><button onclick="closeDialog();audit()">Kontrola pomiarów</button><button onclick="closeDialog()">Zamknij</button></div>`)};
async function openProject(id){if(!await persistProject())return;try{const raw=await ProjectStore.get(id);const next=normalizeProject(raw);data=next;roomId=data.rooms[0].id;wall=0;view='wall';shapeDraft=null;activeElement=null;closeDialog();render();status('● Projekt otwarty');toast('Otwarto „'+data.name+'”.')}catch(e){toast('Nie udało się otworzyć: '+e.message)}}
newProject=async function(){if(!await persistProject())return;const id=uid(),r={id:uid(),name:'Pomieszczenie 1',w:4000,d:3000,h:2700,x:500,y:500,points:Geom.rect(4000,3000),edges:Array.from({length:4},()=>({kind:'wall',start:0,width:0})),elements:[],floorNote:'',ceilingNote:''};const next={id,schema:2,name:'Nowa inwentaryzacja',updatedAt:new Date().toISOString(),rooms:[r],links:[]};try{await ProjectStore.put(next);data=next;roomId=r.id;wall=0;view='wall';activeElement=null;shapeDraft=null;closeDialog();save();render();toast('Utworzono nowy projekt. Poprzedni został zachowany.')}catch{toast('Nie można zapisać nowego projektu. Eksportuj bieżący plik.')}};
async function duplicateProject(){if(!await persistProject())return;const next=copy(data);next.id=uid();next.name=(data.name+' — kopia').slice(0,100);try{await ProjectStore.put(next);data=next;save();closeDialog();render();toast('Utworzono osobną kopię projektu.')}catch{toast('Nie udało się zapisać kopii.')}}
backup=function(){const payload={format:'KiMapka',version:'0.3',exportedAt:new Date().toISOString(),project:copy(data)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='KiMapka-'+data.name.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,60)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Przygotowano plik JSON z pomiarami i zdjęciami.')};
$('#import').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>100*1024*1024)throw Error('Plik przekracza 100 MB.');const next=normalizeProject(JSON.parse(await f.text()));if(!await persistProject())return;next.id=uid();next.updatedAt=new Date().toISOString();await ProjectStore.put(next);data=next;roomId=data.rooms[0].id;wall=0;view='wall';activeElement=null;shapeDraft=null;closeDialog();save();render();toast('Wczytano projekt jako osobny zapis. Poprzedni projekt zachowano.')}catch(e){toast('Import nieudany: '+e.message)}ev.target.value=''};
let showCeiling=false;
sceneSVG=function(scope='room',yaw=sceneYaw,tilt=sceneTilt){const rooms=scope==='all'?data.rooms:[room()],co=Math.cos(yaw),si=Math.sin(yaw),ct=Math.cos(tilt),st=Math.sin(tilt),project=([x,y,z])=>{const a=x*co-y*si,b=x*si+y*co;return [a,b*st-z*ct,b*ct+z*st]},shapes=[],labels=[];
function poly(points,fill,stroke,opacity=1){const pp=points.map(project);shapes.push({depth:pp.reduce((sum,p)=>sum+p[2],0)/pp.length,points:pp,markup:`<polygon points="${pp.map(p=>p.slice(0,2).join(',')).join(' ')}" fill="${fill}" stroke="${stroke}" stroke-width="10" opacity="${opacity}"/>`})}
for(const r of rooms){poly(r.points.map(p=>[r.x+p.x,r.y+p.y,0]),r.id===roomId?'#dce8ee':'#e8eef2','#8da7ba');if(showCeiling)poly(r.points.map(p=>[r.x+p.x,r.y+p.y,r.h]),'#c7dce9','#7597ae',.17);
for(let i=0;i<r.points.length;i++){const e=Geom.edge(r,i),g=Geom.gap(r,i),L=e.len,els=r.elements.filter(q=>q.wall===i),holes=els.filter(q=>['door','window'].includes(q.type)).map(q=>({x:q.x,y:q.y,w:q.w,h:q.h}));if(g)holes.push({x:g[0],y:0,w:g[1]-g[0],h:r.h});const near=((e.dy/L)*si+(-e.dx/L)*co)*ct>0,alpha=sceneCutaway&&near?.12:.82;const xs=[...new Set([0,L,...holes.flatMap(q=>[clamp(q.x,0,L),clamp(q.x+q.w,0,L)])])].sort((a,b)=>a-b),zs=[...new Set([0,r.h,...holes.flatMap(q=>[clamp(q.y,0,r.h),clamp(q.y+q.h,0,r.h)])])].sort((a,b)=>a-b);
for(let a=1;a<xs.length;a++)for(let b=1;b<zs.length;b++){const x=(xs[a-1]+xs[a])/2,z=(zs[b-1]+zs[b])/2;if(holes.some(q=>x>q.x&&x<q.x+q.w&&z>q.y&&z<q.y+q.h))continue;poly([Geom.wallPoint(r,i,xs[a-1],zs[b-1]),Geom.wallPoint(r,i,xs[a],zs[b-1]),Geom.wallPoint(r,i,xs[a],zs[b]),Geom.wallPoint(r,i,xs[a-1],zs[b])],r.id===roomId&&i===wall?'#b4d0df':'#d8e5ee','#8aa5b7',alpha)}const label=project(Geom.wallPoint(r,i,L/2,r.h+130));labels.push(`<text x="${label[0]}" y="${label[1]}" font-size="150" fill="#4c6d83" text-anchor="middle">${String.fromCharCode(65+i)}${r.edges[i].kind!=='wall'?' ◌':''}</text>`)}
for(const e of r.elements){const plane=e.wall<0,z=e.wall===-2?r.h-e.z:e.z,color=e.type==='water'?'#269cab':e.type==='drain'?'#6e7982':e.type==='lamp'?'#e8af3c':isOpening(e)?'#a6becb':'#e7b760',stroke=e.id===activeElement?'#cf7725':'#466a82',pos=(x,y)=>plane?[r.x+x,r.y+y,z]:Geom.wallPoint(r,e.wall,x,y);if(isOpening(e)){const points=plane?[[e.x,e.y],[e.x+e.w,e.y],[e.x+e.w,e.y+e.h],[e.x,e.y+e.h]]:[[e.x,e.y],[e.x+e.w,e.y],[e.x+e.w,e.y+e.h],[e.x,e.y+e.h]];poly(points.map(q=>pos(...q)),e.type==='window'?'#8bc4d5':color,stroke,e.type==='door'?.2:.75);if(plane&&e.type==='obstacle'&&e.z>0){const base=e.wall===-2?r.h:0;for(let k=0;k<4;k++){const a=points[k],b=points[(k+1)%4];poly([[r.x+a[0],r.y+a[1],base],[r.x+b[0],r.y+b[1],base],pos(...b),pos(...a)],color,stroke,.55)}}}else drawPointIcon(e,pos,poly);if(e.id===activeElement){const p=project(pos(e.x,e.y));labels.push(`<text x="${p[0]+100}" y="${p[1]-100}" font-size="140" fill="#915b23">${esc(elName(e))}</text>`)}}
const b=Geom.bounds(r.points),p=project([r.x+b.x+b.w/2,r.y+b.y+b.d/2,0]);labels.push(`<text x="${p[0]}" y="${p[1]}" font-size="150" text-anchor="middle" fill="#36566e">${esc(r.name)}</text>`)}
const all=shapes.flatMap(s=>s.points),minX=Math.min(...all.map(p=>p[0]))-350,maxX=Math.max(...all.map(p=>p[0]))+350,minY=Math.min(...all.map(p=>p[1]))-350,maxY=Math.max(...all.map(p=>p[1]))+250;shapes.sort((a,b)=>a.depth-b.depth);return `<svg viewBox="${minX} ${minY} ${maxX-minX} ${maxY-minY}" aria-label="Model 3D ${scope==='all'?'całego lokalu':esc(room().name)}">${shapes.map(s=>s.markup).join('')}${labels.join('')}</svg>`};
open3D=function(scope=view==='plan'?'all':'room'){sceneScope=scope;$('#dialog').classList.add('scene-dialog');modal(`<div class="scene-heading"><div><div class="eyebrow">BETA 0,3 · GEOMETRIA Z POMIARÓW</div><h2>Podgląd przestrzenny</h2></div><button onclick="closeDialog()">Zamknij</button></div><div class="scene-controls"><select aria-label="Zakres modelu 3D" onchange="sceneScope=this.value;update3D()"><option value="room" ${scope==='room'?'selected':''}>Wybrany pokój</option><option value="all" ${scope==='all'?'selected':''}>Cały lokal</option></select><label><input type="checkbox" ${sceneCutaway?'checked':''} onchange="sceneCutaway=this.checked;update3D()">Odsłoń wnętrze</label><label><input type="checkbox" ${showCeiling?'checked':''} onchange="showCeiling=this.checked;update3D()">Pokaż sufit</label></div><div id="sceneLarge"></div><div class="scene-sliders"><label>Obrót<input aria-label="Obrót modelu 3D" type="range" min="-180" max="180" value="${Math.round(sceneYaw*180/Math.PI)}" oninput="sceneYaw=+this.value*Math.PI/180;update3D()"></label><label>Nachylenie<input aria-label="Nachylenie modelu 3D" type="range" min="15" max="80" value="${Math.round(sceneTilt*180/Math.PI)}" oninput="sceneTilt=+this.value*Math.PI/180;update3D()"></label></div><p class="muted">Podgląd obejmuje własny obrys, otwarte odcinki, ściany, podłogę, sufit i elementy. Turkus: woda · złoty: elektryka. Symbole punktów powiększono. Model poglądowy, bez grubości przegród.</p>`);update3D()};
function planRoom(r){const b=Geom.bounds(r.points);return `<g class="plan-room" data-id="${r.id}" transform="translate(${r.x},${r.y})"><polygon points="${r.points.map(p=>p.x+','+p.y).join(' ')}" fill="${r.id===roomId?'#dceaf0':'#edf2f5'}" stroke="none"/>${r.points.map((p,i)=>{const ed=Geom.edge(r,i),g=Geom.gap(r,i),point=u=>[ed.a.x+ed.dx*u/ed.len,ed.a.y+ed.dy*u/ed.len],seg=(a,z,open)=>`<path d="M${point(a)}L${point(z)}" stroke="${open?'#ce923f':'#466e8b'}" stroke-width="45" ${open?'stroke-dasharray="110 90"':''}/>`;return `${g?seg(0,g[0],false)+seg(g[0],g[1],true)+seg(g[1],ed.len,false):seg(0,ed.len,false)}<text x="${p.x+ed.dx/2+100}" y="${p.y+ed.dy/2-100}" font-size="140" fill="#4c6e84">${String.fromCharCode(65+i)}</text>`}).join('')}<text x="${b.x+b.w/2}" y="${b.y+b.d/2}" text-anchor="middle" font-size="180" fill="#244962">${esc(r.name)}</text><text x="${b.x+b.w/2}" y="${b.y+b.d/2+240}" text-anchor="middle" font-size="140" fill="#678092">${(Geom.area(r.points)/1e6).toFixed(2)} m²</text></g>`}
renderPlan=function(){const points=data.rooms.flatMap(r=>r.points.map(p=>({x:r.x+p.x,y:r.y+p.y}))),b=Geom.bounds(points),pad=600;$('#content').innerHTML=`<div class="room-heading"><div><h2>Plan lokalu</h2><p class="muted">Przesuwaj pokoje. Przerywana linia oznacza otwartą granicę.</p></div><button class="primary" onclick="joinDialog()">⇄ Połącz ściany</button></div><div class="card plan"><div class="card-top"><span class="muted">${data.rooms.length} pomieszczeń · ${(data.rooms.reduce((a,r)=>a+Geom.area(r.points),0)/1e6).toFixed(2)} m² łącznie</span><button onclick="open3D('all')">⤢ Widok 3D</button></div><div class="drawing"><svg id="planSvg" viewBox="${b.x-pad} ${b.y-pad} ${b.w+2*pad} ${b.d+2*pad}" aria-label="Plan całego lokalu">${data.rooms.map(planRoom).join('')}</svg></div></div><div class="connections">${data.links.map(l=>`<div class="connection">${esc(data.rooms.find(r=>r.id===l.a)?.name)} · ${String.fromCharCode(65+l.wa)} ↔ ${esc(data.rooms.find(r=>r.id===l.b)?.name)} · ${String.fromCharCode(65+l.wb)} <span class="muted">${l.t} mm przegrody / przesunięcie ${l.offset} mm</span><button onclick="data.links=data.links.filter(l=>l.id!=='${l.id}');save();renderPlan()">Rozłącz</button></div>`).join('')}</div><div class="callout">Przeciągnięcie pokoju odłącza jego połączenia. Dla otwartych przejść ustaw grubość przegrody 0 mm. Połączenie ustawia obrysy, ale nie tworzy automatycznie otwarcia — oznacz je w edycji obu pomieszczeń.</div><div class="card plan-model"><div class="card-top"><h3>Cały lokal · 3D</h3><button onclick="open3D('all')">Powiększ</button></div><button class="model-mini" id="planMini3D" onclick="open3D('all')" aria-label="Powiększ model całego lokalu"></button></div>`;const svg=$('#planSvg');let drag;const pos=ev=>new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse());svg.onpointerdown=ev=>{const g=ev.target.closest('[data-id]');if(!g)return;const r=data.rooms.find(r=>r.id===g.dataset.id);drag={r,g,p:pos(ev),x:r.x,y:r.y};svg.setPointerCapture(ev.pointerId)};svg.onpointermove=ev=>{if(!drag)return;const p=pos(ev);drag.r.x=Math.round(drag.x+p.x-drag.p.x);drag.r.y=Math.round(drag.y+p.y-drag.p.y);drag.g.setAttribute('transform',`translate(${drag.r.x},${drag.r.y})`);update3D()};const done=ev=>{if(!drag)return;if(ev.type==='pointercancel'){drag.r.x=drag.x;drag.r.y=drag.y}else if(drag.r.x!==drag.x||drag.r.y!==drag.y)data.links=data.links.filter(l=>l.a!==drag.r.id&&l.b!==drag.r.id);roomId=drag.r.id;drag=null;save();render()};svg.onpointerup=done;svg.onpointercancel=done;update3D()};
joinDialog=function(){if(data.rooms.length<2){toast('Dodaj drugie pomieszczenie.');return}const opts=data.rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');modal(`<h2>Połącz wskazane ściany</h2><form id="joinForm"><div class="fields"><div><label>Pokój bazowy</label><select name="a" onchange="joinOptions()">${opts}</select><label>Ściana bazowa</label><select name="wa"></select></div><div><label>Dosuwany pokój</label><select name="b" onchange="joinOptions()">${opts}</select><label>Ściana dosuwana</label><select name="wb"></select></div></div><div class="fields"><div><label>Grubość przegrody · mm</label><input name="t" type="number" min="0" max="2000" value="150" required></div><div><label>Przesunięcie wzdłuż ściany · mm</label><input name="offset" type="number" min="-100000" max="100000" value="0" required></div></div><p class="muted">Wybierz równoległe ściany skierowane przeciwnie. Grubość 0 dla otwartego przejścia. Przesunięcie mierzone od początku ściany bazowej.</p>${actions('Połącz')}</form>`);$('#joinForm [name=b]').selectedIndex=1;joinOptions();$('#joinForm [name=wa]').value='1';$('#joinForm [name=wb]').value=String(Math.min(3,data.rooms[1].points.length-1));$('#joinForm').onsubmit=ev=>{ev.preventDefault();try{const f=new FormData(ev.target),a=data.rooms.find(r=>r.id===f.get('a')),b=data.rooms.find(r=>r.id===f.get('b')),wa=+f.get('wa'),wb=+f.get('wb'),t=+f.get('t'),offset=+f.get('offset');if(a===b)throw Error('Wybierz dwa różne pokoje.');Object.assign(b,Geom.align(a,wa,b,wb,t,offset));data.links=data.links.filter(l=>l.a!==b.id&&l.b!==b.id);data.links.push({id:uid(),a:a.id,b:b.id,wa,wb,t,offset});save();closeDialog();render()}catch(e){toast(e.message)}}};
function joinOptions(){for(const [roomKey,wallKey] of [['a','wa'],['b','wb']]){const r=data.rooms.find(r=>r.id===$(`#joinForm [name=${roomKey}]`).value);$(`#joinForm [name=${wallKey}]`).innerHTML=r.points.map((p,i)=>`<option value="${i}">${String.fromCharCode(65+i)} · ${Math.round(Geom.edge(r,i).len)} mm</option>`).join('')}}
audit=function(){const issues=[];for(const r of data.rooms){for(const e of r.elements)if(!fits(r,e))issues.push(`${r.name} / ${surfaceName(e.wall)}: ${elName(e)} nie mieści się na powierzchni lub koliduje z otwarciem.`);for(const s of [-1,-2])if(!r.elements.some(e=>e.wall===s)&&!(s===-1?r.floorNote:r.ceilingNote))issues.push(`${r.name} / ${surfaceName(s)}: brak elementów i uwag — sprawdź na miejscu.`)}modal(`<h2>Kontrola projektu</h2><p class="muted">Sprawdź także przekątne, pion ścian i poziom podłogi. Brak ostrzeżeń nie potwierdza kompletności pomiaru.</p>${issues.map(s=>`<div class="issue">${esc(s)}</div>`).join('')||'<p>Brak wykrytych problemów.</p>'}<div class="dialog-actions"><button onclick="closeDialog()">Zamknij</button></div>`)};
printReport=function(){document.querySelector('.report')?.remove();const report=document.createElement('div');report.className='report';report.innerHTML=data.rooms.map(r=>[...r.points.map((_,i)=>i),-1,-2].map(w=>`<section><h1>KiMapka BETA 0,3 · ${esc(data.name)}</h1><h2>${esc(r.name)} / ${surfaceName(w)}</h2><p>Powierzchnia ${(Geom.area(r.points)/1e6).toFixed(2)} m² · H ${r.h} mm · powered by KiM Silesia</p>${wallSVG(r,w)}<p>${w<0?'Rzut z góry, X w prawo, Y w dół; sufit bez odbicia. Z: wysokość od podłogi / obniżenie od sufitu.':'X od lewego końca ściany, Y od gotowej podłogi. Otwory i przeszkody: krawędź; punkty: oś.'}</p><p>${esc(w===-1?r.floorNote:w===-2?r.ceilingNote:'')}</p><table><tr><th>Nazwa / typ</th><th>X / Y / Z · mm</th><th>Wymiary · mm</th><th>Opis</th></tr>${r.elements.filter(e=>e.wall===w).map(e=>`<tr><td>${esc(elName(e))} / ${types[e.type][0]}</td><td>${e.x} / ${e.y}${w<0?' / '+e.z:''}</td><td>${isOpening(e)?e.w+' × '+e.h:'—'}</td><td>${esc(e.note)}</td></tr>`).join('')}</table>${r.elements.filter(e=>e.wall===w&&e.photo).map(e=>`<img src="${e.photo}" alt="${esc(elName(e))}">`).join('')}</section>`).join('')).join('');document.body.append(report);window.print()};
const originalReadPhoto02=readPhoto;
openInlinePhoto=function(field,id){photoOwner=id?room().elements.find(e=>e.id===id):room();photoValue=photoOwner.photo||'';ocrTarget=field;$('#inlinePhoto').hidden=false;$('#photoHeading').textContent='Zdjęcie pomiaru · '+$('#'+field).getAttribute('aria-label');$('#photoPreview').hidden=!photoValue;$('#photoPreview').src=photoValue;$('#ocrPanel').innerHTML='';$('#photoInput').value='';$('#photoInput').onchange=async ev=>{const owner=photoOwner,projectId=data.id;try{await originalReadPhoto02(ev);if(data.id===projectId){owner.photo=photoValue;save()}}catch{toast('Nie udało się odczytać zdjęcia. Wybierz plik JPG lub PNG.')}};$('#inlinePhoto').scrollIntoView({behavior:'smooth',block:'nearest'});$('#photoInput').click()};
// Auth controls initialization in beta 0.3.
